// End-to-end smoke test of the running stack, through Caddy, the way real
// clients talk to it: sign-in, tokens, both upload flows, processing, public
// links, filters, trash.
//
//   docker compose down -v && docker compose up -d --build   (needs an EMPTY database)
//   node scripts/smoke.mjs
//
// It asserts exact counts, so it fails on a database that already has assets.
// Test media is generated by ffmpeg inside the worker container.
import { execSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { mkdtempSync, readFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = fileURLToPath(new URL('..', import.meta.url))
const env = Object.fromEntries(
  readFileSync(join(root, '.env'), 'utf8').split('\n').filter((l) => l.includes('=') && !l.startsWith('#')).map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1).trim()]),
)
const BASE = env.PUBLIC_URL

const mediaDir = mkdtempSync(join(tmpdir(), 'prismo-smoke-'))
const ffmpeg = 'ffmpeg -hide_banner -loglevel error -y -f lavfi -i'
execSync(
  `docker compose exec -T worker sh -c "cd /tmp && ${ffmpeg} testsrc=size=640x360:rate=1 -frames:v 1 t.png && ${ffmpeg} testsrc=size=640x360:rate=15 -t 3 -pix_fmt yuv420p -c:v libx264 t.mp4 && ${ffmpeg} testsrc2=size=320x180:rate=10 -t 2 t.gif"`,
  { cwd: root, stdio: 'inherit' },
)
for (const f of ['t.png', 't.mp4', 't.gif']) execSync(`docker compose cp worker:/tmp/${f} "${join(mediaDir, f)}"`, { cwd: root, stdio: 'ignore' })
const media = (n) => readFileSync(join(mediaDir, n))

let cookie = ''
let pass = 0, fail = 0
const check = (name, ok, detail = '') => { ok ? pass++ : fail++; console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  -> ' + detail : ''}`) }

async function call(method, path, { body, token, form, raw, headers = {} } = {}) {
  const h = { ...headers }
  if (token) h.Authorization = `Bearer ${token}`
  else if (cookie) { h.Cookie = cookie; h.Origin = BASE }
  if (body !== undefined) h['Content-Type'] = 'application/json'
  const res = await fetch(path.startsWith('http') ? path : BASE + path, { method, headers: h, body: form ?? (body !== undefined ? JSON.stringify(body) : raw), redirect: 'manual' })
  const text = await res.text()
  let json = null
  try { json = JSON.parse(text) } catch {}
  return { status: res.status, json, text, headers: res.headers }
}

async function waitReady(id, token) {
  for (let i = 0; i < 60; i++) {
    const r = await call('GET', `/v1/assets/${id}`, token ? { token } : {})
    if (r.json?.status === 'ready' || r.json?.status === 'failed') return r.json
    await new Promise((r) => setTimeout(r, 500))
  }
  return null
}

function multipart(name, buf, fields = {}) {
  const f = new FormData()
  for (const [k, v] of Object.entries(fields)) f.set(k, v)
  f.set('file', new Blob([buf]), name)
  return f
}

// --- auth ---
let r = await call('GET', '/v1/me')
check('me without session is 401', r.status === 401)
r = await call('POST', '/v1/auth/login', { body: { email: 'a@b.c', password: 'x' } })
check('password sign-in no longer exists', r.status === 404 || r.status === 405, String(r.status))
r = await call('GET', '/v1/auth/config')
const signIn = r.json
check('sign-in options are announced', r.status === 200 && signIn.dev === true, JSON.stringify(signIn))

if (signIn.google) {
  // The trip to Google, as far as it can be checked without a real account.
  r = await call('GET', '/v1/auth/google/start')
  const to = new URL(r.headers.get('location') ?? 'http://none')
  const oauthCookie = (r.headers.get('set-cookie') ?? '').split(';')[0]
  check('google start redirects to Google with the right request', r.status === 302 && to.host === 'accounts.google.com' && to.searchParams.get('response_type') === 'id_token' && to.searchParams.get('response_mode') === 'form_post' && to.searchParams.get('redirect_uri') === BASE + '/v1/auth/google/callback' && to.searchParams.get('client_id') === (process.env.GOOGLE_CLIENT_ID || env.GOOGLE_CLIENT_ID) && !!to.searchParams.get('nonce'), to.origin + to.pathname)
  check('state cookie can ride a cross-site POST', /samesite=none/i.test(r.headers.get('set-cookie') ?? '') && /secure/i.test(r.headers.get('set-cookie') ?? '') && /httponly/i.test(r.headers.get('set-cookie') ?? ''))
  const answer = (cookieHeader, fields) => fetch(BASE + '/v1/auth/google/callback', { method: 'POST', redirect: 'manual', headers: { 'Content-Type': 'application/x-www-form-urlencoded', Origin: 'https://accounts.google.com', ...(cookieHeader ? { Cookie: cookieHeader } : {}) }, body: new URLSearchParams(fields) })
  const forged = ['eyJhbGciOiJub25lIn0', Buffer.from(JSON.stringify({ iss: 'https://accounts.google.com', aud: env.GOOGLE_CLIENT_ID, sub: '1', email: 'attacker@example.com', email_verified: true, nonce: to.searchParams.get('nonce'), exp: 9999999999 })).toString('base64url'), ''].join('.')
  r = await answer('', { state: to.searchParams.get('state'), id_token: forged })
  check('callback without the state cookie is refused', r.status === 303 && r.headers.get('location') === '/?auth_error=expired' && !/prismo_session=\w/.test(r.headers.get('set-cookie') ?? ''), r.headers.get('location'))
  r = await answer(oauthCookie, { state: 'someone-elses-state', id_token: forged })
  check('callback with the wrong state is refused', r.headers.get('location') === '/?auth_error=expired', r.headers.get('location'))
  r = await answer(oauthCookie, { state: to.searchParams.get('state'), id_token: forged })
  check('unsigned token is refused', r.headers.get('location') === '/?auth_error=invalid' && !/prismo_session=\w/.test(r.headers.get('set-cookie') ?? ''), r.headers.get('location'))
  r = await answer(oauthCookie, { state: to.searchParams.get('state'), error: 'access_denied' })
  check('cancelling at Google is reported', r.headers.get('location') === '/?auth_error=cancelled', r.headers.get('location'))
} else {
  r = await call('GET', '/v1/auth/google/start')
  check('google start is 404 when no client id is set (google checks skipped)', r.status === 404)
}

r = await call('POST', '/v1/auth/dev', { headers: { Origin: BASE } })
cookie = (r.headers.get('set-cookie') ?? '').split(';')[0]
check('development sign-in', r.status === 204 && cookie.startsWith('prismo_session='), `HttpOnly=${/httponly/i.test(r.headers.get('set-cookie') ?? '')}`)
r = await call('GET', '/v1/me')
check('me', r.status === 200 && r.json.user.email === 'dev@localhost')
r = await fetch(BASE + '/v1/collections', { method: 'POST', headers: { Cookie: cookie, Origin: 'http://evil.example', 'Content-Type': 'application/json' }, body: '{"name":"x"}' })
check('cross-site POST with cookie refused', r.status === 403)
r = await call('GET', '/v1/collections')
check('default jars seeded', r.json.collections.map((c) => c.name).join() === 'gifs,screenshots,stickers', r.json.collections.map((c) => c.name).join())

// --- tokens ---
r = await call('POST', '/v1/tokens', { body: { name: 'e2e sharex', scope: 'upload', default_visibility: 'unlisted' } })
const upTok = r.json?.secret
check('create upload token', r.status === 201 && upTok?.startsWith('prismo_'))
r = await call('GET', '/v1/assets', { token: upTok })
check('upload token cannot list', r.status === 403)
r = await call('POST', '/v1/tokens', { token: upTok, body: { name: 'x', scope: 'full' } })
check('token cannot mint tokens', r.status === 403)
r = await call('GET', '/v1/assets', { token: 'prismo_nope' })
check('bad token is 401', r.status === 401)

// --- ShareX-style upload: PNG ---
r = await call('POST', '/v1/upload', { token: upTok, form: multipart('shot one.png', media('t.png'), { collection: 'screenshots', source: 'sharex', tags: 'Test, e2e' }) })
check('sharex upload png', r.status === 201 && r.json.url.endsWith('.png'), `${r.status} ${r.json?.url ?? r.text.slice(0, 120)}`)
const png = r.json
let a = await waitReady(png.id)
check('png ready', a?.status === 'ready' && a.kind === 'image' && a.mime === 'image/png' && a.width === 640 && a.height === 360, JSON.stringify({ s: a?.status, k: a?.kind, m: a?.mime, w: a?.width, h: a?.height, v: a?.variants, e: a?.error }))
check('png has thumb, tags, jar, unlisted', a?.variants.includes('thumb') && a.tags.join() === 'test,e2e' && a.collection_id && a.visibility === 'unlisted' && a.source === 'sharex')
r = await fetch(png.url)
let buf = Buffer.from(await r.arrayBuffer())
check('public /i/slug.png serves original bytes', r.status === 200 && r.headers.get('content-type') === 'image/png' && buf.equals(media('t.png')), `${r.status} ${r.headers.get('content-type')} cache=${r.headers.get('cache-control')} nosniff=${r.headers.get('x-content-type-options')}`)
r = await fetch(png.thumb_url)
check('public thumb is webp', r.status === 200 && r.headers.get('content-type') === 'image/webp', `${r.status} ${r.headers.get('content-type')}`)
r = await fetch(png.share_url)
let html = await r.text()
check('share page has og:image', r.status === 200 && html.includes('property="og:image"') && html.includes('summary_large_image'))
r = await fetch(png.url, { headers: { 'If-None-Match': r.headers.get('etag') ?? '' } })
const etag = (await fetch(png.url)).headers.get('etag')
r = await fetch(png.url, { headers: { 'If-None-Match': etag } })
check('etag revalidation gives 304', r.status === 304, etag?.slice(0, 14))

// --- duplicate ---
r = await call('POST', '/v1/upload', { token: upTok, form: multipart('again.png', media('t.png')) })
check('same file again is a duplicate', r.status === 200 && r.json.duplicate === true && r.json.id === png.id)

// --- video -> gif ---
r = await call('POST', '/v1/upload', { token: upTok, form: multipart('clip.mp4', media('t.mp4'), { collection: 'gifs' }) })
const vid = r.json
check('sharex upload mp4', r.status === 201 && vid.gif_url.endsWith('.gif'), vid?.gif_url)
// fetch the gif link right away: it must wait for processing instead of 404
const t0 = Date.now()
r = await fetch(vid.gif_url)
buf = Buffer.from(await r.arrayBuffer())
check('gif link works immediately after upload', r.status === 200 && r.headers.get('content-type') === 'image/gif' && buf.subarray(0, 4).toString() === 'GIF8', `${r.status} ${r.headers.get('content-type')} ${buf.length}B waited ${Date.now() - t0}ms`)
a = await waitReady(vid.id)
check('video ready with gif + thumb + duration', a?.kind === 'video' && a.variants.includes('gif') && a.variants.includes('thumb') && a.duration_ms >= 2900 && a.duration_ms <= 3200, JSON.stringify({ k: a?.kind, v: a?.variants, d: a?.duration_ms, m: a?.mime }))
r = await fetch(vid.url, { headers: { Range: 'bytes=0-99' } })
check('range request on video gives 206', r.status === 206 && r.headers.get('content-range')?.startsWith('bytes 0-99/'), `${r.status} ${r.headers.get('content-range')}`)
r = await fetch(vid.share_url)
html = await r.text()
check('video share page has og:video', html.includes('property="og:video"') && html.includes('twitter:card" content="player"'))

// --- gif -> mp4 ---
r = await call('POST', '/v1/upload', { token: upTok, form: multipart('anim.gif', media('t.gif')) })
const gif = r.json
a = await waitReady(gif.id)
check('gif ready with mp4 version', a?.kind === 'gif' && a.variants.includes('mp4') && a.variants.includes('thumb'), JSON.stringify({ k: a?.kind, v: a?.variants }))
r = await fetch(`${BASE}/i/${a.slug}.mp4`)
check('/i/slug.mp4 of a gif is video', r.status === 200 && r.headers.get('content-type') === 'video/mp4', `${r.status} ${r.headers.get('content-type')}`)

// --- direct-to-storage upload (what the web app does) ---
const body2 = Buffer.concat([media('t.png'), Buffer.from('different-tail')])
const sha = createHash('sha256').update(body2).digest('hex')
r = await call('POST', '/v1/assets', { body: { filename: 'direct.png', bytes: body2.length, sha256: sha, collection: 'screenshots' } })
check('create upload slot', r.status === 201 && r.json.upload?.url.startsWith(env.S3_PUBLIC_ENDPOINT), r.json?.upload?.url.split('?')[0] ?? r.text.slice(0, 200))
const slot = r.json
r = await fetch(slot.upload.url, { method: 'OPTIONS', headers: { Origin: BASE, 'Access-Control-Request-Method': 'PUT', 'Access-Control-Request-Headers': 'content-type' } })
check('storage answers CORS preflight for the app origin', r.headers.get('access-control-allow-origin') === BASE, `${r.status} allow-origin=${r.headers.get('access-control-allow-origin')}`)
r = await fetch(slot.upload.url, { method: 'OPTIONS', headers: { Origin: 'http://evil.example', 'Access-Control-Request-Method': 'PUT' } })
check('storage refuses CORS preflight for other origins', r.status === 403, `${r.status}`)
r = await fetch(slot.upload.url, { method: 'PUT', body: body2, headers: { Origin: BASE } })
check('PUT straight to storage', r.status === 200, `${r.status} ${(await r.text()).slice(0, 160)}`)
r = await call('POST', `/v1/assets/${slot.asset.id}/complete`)
check('complete', r.status === 200 && r.json.status === 'processing', `${r.status} ${r.json?.status ?? r.text.slice(0, 160)}`)
a = await waitReady(slot.asset.id)
check('direct upload ready, private by default', a?.status === 'ready' && a.visibility === 'private' && a.source === 'web', JSON.stringify({ s: a?.status, v: a?.visibility, src: a?.source, e: a?.error }))
r = await fetch(`${BASE}/i/${a.slug}`)
check('private asset is 404 for strangers', r.status === 404)
r = await call('GET', `/i/${a.slug}`)
check('private asset visible to owner', r.status === 200)
r = await call('POST', '/v1/assets', { body: { filename: 'direct2.png', bytes: body2.length, sha256: sha } })
check('known hash skips upload', r.status === 200 && r.json.duplicate === true && !r.json.upload)

// --- wrong content: checksum mismatch and disguised html ---
r = await call('POST', '/v1/assets', { body: { filename: 'liar.png', bytes: 5, sha256: 'a'.repeat(64) } })
await fetch(r.json.upload.url, { method: 'PUT', body: 'hello' })
await call('POST', `/v1/assets/${r.json.asset.id}/complete`)
a = await waitReady(r.json.asset.id)
check('checksum mismatch fails the asset', a?.status === 'failed', a?.error)
r = await call('POST', '/v1/upload', { token: upTok, form: multipart('cat.png', Buffer.from('<html><script>alert(1)</script></html>')) })
a = await waitReady(r.json.id)
r = await fetch(r.json.url)
check('html named .png is not served as image or inline', a?.kind === 'file' && r.headers.get('content-type') === 'application/octet-stream' && r.headers.get('content-disposition').startsWith('attachment'), `${a?.kind} ${r.headers.get('content-type')} ${r.headers.get('content-disposition')}`)

// --- list / filter / edit / trash ---
r = await call('GET', '/v1/assets?limit=2')
check('list page 1 with cursor', r.json.assets.length === 2 && typeof r.json.next_cursor === 'string')
const firstIds = r.json.assets.map((x) => x.id)
r = await call('GET', `/v1/assets?limit=2&cursor=${r.json.next_cursor}`)
check('list page 2 has no overlap', r.json.assets.length >= 1 && !r.json.assets.some((x) => firstIds.includes(x.id)))
r = await call('GET', '/v1/assets?kind=video')
check('filter by kind', r.json.assets.length === 1 && r.json.assets[0].id === vid.id)
r = await call('GET', '/v1/assets?tag=e2e')
check('filter by tag', r.json.assets.length === 1 && r.json.assets[0].id === png.id)
r = await call('GET', '/v1/assets?q=shot%20one')
check('search by name', r.json.assets.length === 1 && r.json.assets[0].id === png.id)
r = await call('PATCH', `/v1/assets/${png.id}`, { body: { title: 'Renamed', tags: ['A', 'b', 'a'], collection_id: null, visibility: 'public', kind: 'sticker' } })
check('patch asset', r.status === 200 && r.json.title === 'Renamed' && r.json.tags.join() === 'a,b' && r.json.collection_id === null && r.json.visibility === 'public' && r.json.kind === 'sticker', r.text.slice(0, 160))
r = await call('PATCH', `/v1/assets/${png.id}`, { body: { visibility: 'everyone' } })
check('bad visibility rejected', r.status === 400)
r = await call('DELETE', `/v1/assets/${png.id}`)
check('trash', r.status === 204)
r = await fetch(png.url)
check('trashed asset link is 404', r.status === 404)
r = await call('GET', '/v1/assets?trashed=1')
check('trash lists it', r.json.assets.some((x) => x.id === png.id))
r = await call('POST', `/v1/assets/${png.id}/restore`)
check('restore', r.status === 204)
r = await call('POST', '/v1/assets/bulk', { body: { ids: [gif.id, vid.id], action: 'visibility', visibility: 'private' } })
check('bulk visibility', r.json?.changed === 2)
r = await call('POST', '/v1/assets/bulk', { body: { ids: [gif.id], action: 'trash' } })
r = await call('POST', '/v1/assets/bulk', { body: { ids: [gif.id], action: 'purge' } })
check('bulk purge', r.json?.changed === 1)
r = await call('GET', `/v1/assets/${gif.id}`)
check('purged asset is gone', r.status === 404)
r = await call('GET', '/v1/assets/not-a-uuid')
check('malformed id is 404, not 500', r.status === 404)
r = await call('GET', '/v1/stats')
check('stats', r.status === 200 && r.json.assets >= 4 && r.json.bytes > 0, JSON.stringify(r.json))
r = await call('GET', '/v1/tags')
check('tags', r.json.tags.some((t) => t.tag === 'a'))

// --- sharing with a specific person ---
const ownerCookie = cookie
const jar = (await call('GET', '/v1/collections')).json.collections.find((c) => c.name === 'screenshots')
const otherJar = (await call('GET', '/v1/collections')).json.collections.find((c) => c.name === 'gifs')
const inJar = slot.asset.id // direct.png: in "screenshots", private
const outside = vid.id // clip.mp4: in "gifs", private
const signInAs = async (email) => {
  const res = await fetch(BASE + '/v1/auth/dev', { method: 'POST', headers: { Origin: BASE, 'Content-Type': 'application/json' }, body: JSON.stringify({ email }) })
  return { status: res.status, cookie: (res.headers.get('set-cookie') ?? '').split(';')[0] }
}

r = await signInAs('guest@example.com')
check('someone nothing is shared with cannot sign in', r.status === 403)
r = await call('POST', '/v1/shares', { body: { collection_id: jar.id, email: 'Guest@Example.com', role: 'view' } })
const share = r.json
check('owner shares a jar (view)', r.status === 201 && share.email === 'guest@example.com' && share.invite_url.startsWith(BASE + '/?invite='), r.text.slice(0, 120))
r = await fetch(`${BASE}/v1/invites/${share.invite_url.split('invite=')[1]}`)
const inv = await r.json()
check('invitation link names the invited account, no sign-in needed', r.status === 200 && inv.email === 'guest@example.com' && inv.name === 'screenshots' && inv.role === 'view' && inv.owner === 'dev@localhost', JSON.stringify(inv))
r = await fetch(`${BASE}/v1/invites/${'x'.repeat(40)}`)
check('unknown invitation is 404', r.status === 404)
r = await call('POST', '/v1/shares', { body: { collection_id: otherJar.id, email: 'nobody', role: 'view' } })
check('share needs a real address', r.status === 400)
r = await call('POST', '/v1/shares', { body: { collection_id: jar.id, email: 'x@example.com', role: 'admin' } })
check('share needs a known role', r.status === 400)

const guest = await signInAs('guest@example.com')
check('invited guest can sign in', guest.status === 204 && guest.cookie.startsWith('prismo_session='))
cookie = guest.cookie
r = await call('GET', '/v1/me')
check('guest is not a member', r.json.member === false && r.json.user.email === 'guest@example.com')
r = await call('GET', '/v1/shared')
check('guest sees the shared jar', r.json.jars.length === 1 && r.json.jars[0].id === jar.id && r.json.jars[0].role === 'view' && r.json.jars[0].owner === 'dev@localhost', JSON.stringify(r.json.jars))
r = await call('GET', `/v1/shared/jars/${jar.id}/assets`)
check('guest can list the shared jar, read-only', r.status === 200 && r.json.assets.some((x) => x.id === inJar) && r.json.assets.every((x) => x.access === 'view' && x.collection_id === jar.id) && r.json.jar.name === 'screenshots')
r = await call('GET', `/v1/assets/${inJar}/file`)
check('guest can open a file in it', r.status === 200)
r = await call('GET', '/v1/assets')
check('guest has no library of their own', r.json.assets.length === 0)
r = await call('GET', `/v1/assets/${outside}`)
check('guest cannot reach items outside the jar', r.status === 404)
r = await call('GET', `/v1/shared/jars/${otherJar.id}/assets`)
check('guest cannot list a jar that was not shared', r.status === 404)
r = await call('GET', `/v1/shared/jars/${jar.id}/assets?collection=${otherJar.id}`)
check('query string cannot widen the listing', r.json.assets.every((x) => x.collection_id === jar.id))
r = await call('PATCH', `/v1/assets/${inJar}`, { body: { title: 'changed' } })
check('view cannot rename', r.status === 403)
r = await call('DELETE', `/v1/assets/${inJar}`)
check('view cannot delete', r.status === 403)
r = await call('POST', '/v1/assets', { body: { filename: 'g.png', bytes: 10, collection_id: jar.id } })
check('view cannot add files', r.status === 400, r.json?.error)
r = await call('POST', '/v1/assets', { body: { filename: 'g.png', bytes: 10 } })
check('guest cannot upload into a library of their own', r.status === 400, r.json?.error)
r = await call('POST', '/v1/tokens', { body: { name: 'x', scope: 'full' } })
check('guest cannot mint tokens', r.status === 403)
r = await call('POST', '/v1/shares', { body: { collection_id: jar.id, email: 'third@example.com', role: 'view' } })
check('guest cannot pass access on', r.status === 403)
r = await call('POST', '/v1/collections', { body: { name: 'mine' } })
check('guest cannot create jars', r.status === 403)

cookie = ownerCookie
r = await call('PATCH', `/v1/shares/${share.id}`, { body: { role: 'edit' } })
check('owner upgrades the share to edit', r.status === 200 && r.json.role === 'edit')
cookie = guest.cookie
r = await call('PATCH', `/v1/assets/${inJar}`, { body: { title: 'renamed by guest', tags: ['shared'] } })
check('edit can rename and tag', r.status === 200 && r.json.title === 'renamed by guest' && r.json.access === 'edit')
r = await call('PATCH', `/v1/assets/${inJar}`, { body: { visibility: 'public' } })
check('edit cannot change who can see it', r.status === 403)
r = await call('PATCH', `/v1/assets/${inJar}`, { body: { collection_id: null } })
check('edit cannot move it out of the jar', r.status === 403)
const guestFile = Buffer.concat([media('t.png'), Buffer.from('from-guest')])
r = await call('POST', '/v1/assets', { body: { filename: 'from-guest.png', bytes: guestFile.length, collection_id: jar.id, visibility: 'public' } })
const guestSlot = r.json
check('edit can start an upload into the jar, but not make it public', r.status === 201 && guestSlot.asset.visibility === 'private', r.text.slice(0, 140))
await fetch(guestSlot.upload.url, { method: 'PUT', body: guestFile })
r = await call('POST', `/v1/assets/${guestSlot.asset.id}/complete`)
check('guest completes the upload', r.status === 200, r.text.slice(0, 120))
a = await waitReady(guestSlot.asset.id)
check('guest upload gets processed', a?.status === 'ready' && a.access === 'edit', JSON.stringify({ s: a?.status, acc: a?.access, e: a?.error }))
cookie = ownerCookie
r = await call('GET', `/v1/assets/${guestSlot.asset.id}`)
check('the file belongs to the jar owner and is private', r.status === 200 && r.json.access === 'owner' && r.json.visibility === 'private' && r.json.source === 'guest' && r.json.collection_id === jar.id)
cookie = guest.cookie
r = await call('DELETE', `/v1/assets/${guestSlot.asset.id}?permanent=1`)
check('edit cannot delete for good', r.status === 403)
r = await call('DELETE', `/v1/assets/${guestSlot.asset.id}`)
check('edit can move to trash', r.status === 204)
r = await call('GET', `/v1/assets/${guestSlot.asset.id}`)
check('a trashed item disappears for the guest', r.status === 404)
cookie = ownerCookie
r = await call('GET', '/v1/assets?trashed=1')
check('owner finds it in the trash and can restore it', r.json.assets.some((x) => x.id === guestSlot.asset.id))

r = await call('POST', '/v1/shares', { body: { asset_id: outside, email: 'guest@example.com', role: 'view' } })
const itemShare = r.json
check('owner shares one item', r.status === 201 && itemShare.asset_id === outside)
const outsideSlug = (await call('GET', `/v1/assets/${outside}`)).json.slug
cookie = guest.cookie
r = await call('GET', '/v1/shared')
check('guest sees the single item', r.json.items.length === 1 && r.json.items[0].id === outside && r.json.items[0].access === 'view' && r.json.items[0].owner === 'dev@localhost')
r = await call('GET', `/i/${outsideSlug}`)
check('its private link opens for the invited guest', r.status === 200)
r = await fetch(`${BASE}/i/${outsideSlug}`)
check('and stays closed to everyone else', r.status === 404)
r = await fetch(`${BASE}/v1/assets/${png.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: '{"title":"x"}' })
check('a public link gives no way to edit', r.status === 401)

cookie = ownerCookie
r = await call('GET', `/v1/shares?collection=${jar.id}`)
check('owner lists who a jar is shared with', r.json.shares.length === 1 && r.json.shares[0].email === 'guest@example.com' && r.json.shares[0].role === 'edit')
r = await call('DELETE', `/v1/shares/${share.id}`)
await call('DELETE', `/v1/shares/${itemShare.id}`)
check('owner revokes', r.status === 204)
cookie = guest.cookie
r = await call('GET', `/v1/assets/${inJar}`)
check('after revoking, the guest is locked out at once', r.status === 404)
r = await call('GET', '/v1/shared')
check('and sees nothing shared', r.json.jars.length === 0 && r.json.items.length === 0)
r = await signInAs('guest@example.com')
check('and cannot sign in again', r.status === 403)
cookie = ownerCookie

// --- logout ---
r = await call('POST', '/v1/auth/logout')
r = await call('GET', '/v1/me')
check('logout ends the session', r.status === 401)

console.log(`\n${pass} passed, ${fail} failed`)
process.exit(fail ? 1 : 0)
